macro_rules! ABM_DCN301_REG_LIST { ($id:expr) => { ABM_COMMON_REG_LIST_DCE_BASE!(), SRI!(DC_ABM1_HG_SAMPLE_RATE, ABM, $id), SRI!(DC_ABM1_LS_SAMPLE_RATE, ABM, $id), SRI!(BL1_PWM_BL_UPDATE_SAMPLE_RATE, ABM, $id), SRI!(DC_ABM1_HG_MISC_CTRL, ABM, $id), SRI!(DC_ABM1_IPCSC_COEFF_SEL, ABM, $id), SRI!(BL1_PWM_CURRENT_ABM_LEVEL, ABM, $id), SRI!(BL1_PWM_TARGET_ABM_LEVEL, ABM, $id), SRI!(BL1_PWM_USER_LEVEL, ABM, $id), SRI!(DC_ABM1_LS_MIN_MAX_PIXEL_VALUE_THRES, ABM, $id), SRI!(DC_ABM1_HGLS_REG_READ_PROGRESS, ABM, $id), NBIO_SR!(BIOS_SCRATCH_2) }; }
