macro_rules! ABM_SF { ($reg:ident, $field:ident, $post_fix:ident) => { .$field = concat!(stringify!($reg), "__", stringify!($field), stringify!($post_fix)) }; }
macro_rules! ABM_COMMON_MASK_SH_LIST_DCE_COMMON_BASE { ($mask_sh:ident) => { ABM_SF!(MASTER_COMM_CNTL_REG, MASTER_COMM_INTERRUPT, $mask_sh), ABM_SF!(MASTER_COMM_CMD_REG, MASTER_COMM_CMD_REG_BYTE0, $mask_sh), ABM_SF!(MASTER_COMM_CMD_REG, MASTER_COMM_CMD_REG_BYTE1, $mask_sh), ABM_SF!(MASTER_COMM_CMD_REG, MASTER_COMM_CMD_REG_BYTE2, $mask_sh) }; }
macro_rules! ABM_MASK_SH_LIST_DCE110 { ($mask_sh:ident) => { ABM_COMMON_MASK_SH_LIST_DCE_COMMON_BASE!($mask_sh) }; }
macro_rules! ABM_MASK_SH_LIST_DCN10_COMMON { ($mask_sh:ident) => { ABM_SF!(ABM0_DC_ABM1_HG_MISC_CTRL, ABM1_HG_NUM_OF_BINS_SEL, $mask_sh), ABM_SF!(ABM0_DC_ABM1_HG_MISC_CTRL, ABM1_HG_VMAX_SEL, $mask_sh), ABM_SF!(ABM0_DC_ABM1_HG_MISC_CTRL, ABM1_HG_BIN_BITWIDTH_SIZE_SEL, $mask_sh), ABM_SF!(ABM0_DC_ABM1_IPCSC_COEFF_SEL, ABM1_IPCSC_COEFF_SEL_R, $mask_sh), ABM_SF!(ABM0_DC_ABM1_IPCSC_COEFF_SEL, ABM1_IPCSC_COEFF_SEL_G, $mask_sh), ABM_SF!(ABM0_DC_ABM1_IPCSC_COEFF_SEL, ABM1_IPCSC_COEFF_SEL_B, $mask_sh) }; }
macro_rules! ABM_MASK_SH_LIST_DCN10 { ($mask_sh:ident) => { ABM_COMMON_MASK_SH_LIST_DCE_COMMON_BASE!($mask_sh), ABM_MASK_SH_LIST_DCN10_COMMON!($mask_sh) }; }
macro_rules! ABM_MASK_SH_LIST_DCN20 { ($mask_sh:ident) => { ABM_MASK_SH_LIST_DCE110!($mask_sh) }; }
macro_rules! ABM_MASK_SH_LIST_DCN30 { ($mask_sh:ident) => { ABM_MASK_SH_LIST_DCN10!($mask_sh) }; }
macro_rules! ABM_MASK_SH_LIST_DCN35 { ($mask_sh:ident) => { ABM_MASK_SH_LIST_DCN10_COMMON!($mask_sh) }; }
macro_rules! ABM_MASK_SH_LIST_DCN32 { ($mask_sh:ident) => { ABM_MASK_SH_LIST_DCN10_COMMON!($mask_sh) }; }
macro_rules! ABM_MASK_SH_LIST_DCN401 { ($mask_sh:ident) => { ABM_MASK_SH_LIST_DCN10_COMMON!($mask_sh) }; }
macro_rules! ABM_MASK_SH_LIST_DCN42 { ($mask_sh:ident) => { ABM_MASK_SH_LIST_DCN10_COMMON!($mask_sh) }; }

